def transform(grid):
    # Return the lower-rightmost isolated object, tightly cropped.
    R,C=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(R):
        for c in range(C):
            if not grid[r][c] or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx in (-1,0,1):
                    for dy in (-1,0,1):
                        q=(x+dx,y+dy)
                        if (dx or dy) and 0<=q[0]<R and 0<=q[1]<C and grid[q[0]][q[1]] and q not in seen:
                            seen.add(q); stack.append(q)
            objs.append(cells)
    cells=max(objs,key=lambda o:(max(r for r,c in o),max(c for r,c in o)))
    r0=min(r for r,c in cells);r1=max(r for r,c in cells);c0=min(c for r,c in cells);c1=max(c for r,c in cells)
    return [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
